'use strict';

// Pretend-database. Items are inserted in id order; query helpers preserve
// that order so cursor pagination has stable semantics.
const items = Array.from({ length: 50 }, (_, i) => ({
  _id: String(i + 1).padStart(4, '0'),
  name: `Item ${i + 1}`,
  created_at: new Date(2026, 0, i + 1).toISOString(),
}));

function listAll() { return items.slice(); }

function findById(id) { return items.find(it => it._id === id) || null; }

module.exports = { listAll, findById };

'use strict';

const express = require('express');
const itemStore = require('./itemStore');

function makeApp() {
  const app = express();
  app.use(express.json());

  // TODO: add cursor-based pagination.
  app.get('/api/items', (req, res) => {
    const items = itemStore.listAll();
    res.json({ items, next_cursor: null });
  });

  return app;
}

module.exports = { makeApp };

if (require.main === module) {
  const app = makeApp();
  app.listen(3000, () => console.log('listening on :3000'));
}

const request = require('supertest');
const { makeApp } = require('../src/server');

const app = makeApp();

test('baseline: GET /api/items returns items', async () => {
  const res = await request(app).get('/api/items');
  expect(res.status).toBe(200);
  expect(Array.isArray(res.body.items)).toBe(true);
  expect(res.body.items.length).toBeGreaterThan(0);
});

'use strict';

const express = require('express');
const itemStore = require('./itemStore');

const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

function makeApp() {
  const app = express();
  app.use(express.json());

  app.get('/api/items', (req, res) => {
    let limit = req.query.limit === undefined ? DEFAULT_LIMIT : Number(req.query.limit);
    if (!Number.isFinite(limit) || !Number.isInteger(limit) || limit < 1 || limit > MAX_LIMIT) {
      return res.status(400).json({ error: 'invalid_limit' });
    }

    const all = itemStore.listAll();
    let startIdx = 0;
    if (req.query.cursor !== undefined) {
      const idx = all.findIndex(it => it._id === String(req.query.cursor));
      if (idx === -1) return res.status(400).json({ error: 'invalid_cursor' });
      startIdx = idx + 1;
    }

    const slice = all.slice(startIdx, startIdx + limit);
    const next_cursor = startIdx + limit < all.length ? slice[slice.length - 1]._id : null;
    res.json({ items: slice, next_cursor });
  });

  return app;
}

module.exports = { makeApp };

