npm install --silent --no-audit --no-fund && cat > tests/hidden.test.js <<'EOF'
const request = require('supertest');
const { makeApp } = require('../src/server');
const app = makeApp();

test('default limit is 20', async () => {
  const r = await request(app).get('/api/items');
  expect(r.body.items.length).toBe(20);
  expect(r.body.next_cursor).toBeTruthy();
});

test('cursor advances the page', async () => {
  const a = await request(app).get('/api/items?limit=5');
  const b = await request(app).get(`/api/items?limit=5&cursor=${a.body.next_cursor}`);
  expect(b.body.items.map(i => i._id)).not.toEqual(a.body.items.map(i => i._id));
  expect(b.body.items.length).toBe(5);
});

test('invalid limit returns 400', async () => {
  const r = await request(app).get('/api/items?limit=999');
  expect(r.status).toBe(400);
  expect(r.body.error).toBe('invalid_limit');
});

test('invalid cursor returns 400', async () => {
  const r = await request(app).get('/api/items?cursor=does-not-exist');
  expect(r.status).toBe(400);
  expect(r.body.error).toBe('invalid_cursor');
});
